const webhookData = $('Webhook pliego-definitivo-empresa').item.json.body;
const faseData = $('Postgres - Obtener fase').item.json;
const empresa = $('Postgres - Obtener empresa').item.json;
const documentosBase64 = webhookData.documentosBase64 || [];
// Leer resumen extraído por Haiku
const haikuResponse = $('Claude Haiku - Extraer documentos').item.json;
let resumenDocumentos = 'Sin documentos adjuntos.';
if (haikuResponse.content && haikuResponse.content[0] && haikuResponse.content[0].text) {
  resumenDocumentos = haikuResponse.content[0].text.trim() || 'Sin contenido extraíble.';
}
if (haikuResponse.stop_reason === 'max_tokens') {
  resumenDocumentos = '[ADVERTENCIA: resumen de documentos truncado — Haiku alcanzó max_tokens]\n' + resumenDocumentos;
}



const analisisGeneral = faseData.analisis_claude?.general || {};
const empresaId = empresa.id;

const systemPrompt = 'Eres un experto juridico en contratacion publica colombiana. Analiza en profundidad si la empresa puede presentar oferta en esta licitacion segun el pliego definitivo. Devuelve UNICAMENTE un JSON valido (sin markdown): {"veredicto_final":"va|no_va|va_con_riesgos","resumen_ejecutivo":"string","requisitos":[{"categoria":"juridico|financiero|tecnico|experiencia","requisito":"string","estado":"cumple|no_cumple|dudoso","justificacion":"string"}],"fortalezas":["string"],"debilidades":["string"],"recomendacion_anexos":"string"}';

const perfil = empresa.contexto_procesado ? JSON.stringify(empresa.contexto_procesado) : 'Sin perfil';
const reqHab = JSON.stringify(analisisGeneral.requisitos_habilitantes || {});
const criterios = JSON.stringify(analisisGeneral.criterios_ponderacion || []);

const userText = 'EMPRESA A EVALUAR:\nID: ' + empresaId + '\nNombre: ' + empresa.nombre + '\nNIT: ' + empresa.nit + '\nPerfil completo: ' + perfil + '\n\nREQUISITOS HABILITANTES DEL PLIEGO:\n' + reqHab + '\n\nCRITERIOS DE PONDERACION:\n' + criterios + '\n\nA continuacion el pliego definitivo completo.';

// Documentos resumidos por Haiku — no se envían en base64 a Sonnet);
}

const requestBody = {
  model: 'claude-sonnet-4-6',
  max_tokens: 8192,
  system: systemPrompt,
  messages: [{ role: 'user', content: [{ type: 'text', text: userText + '

=== RESUMEN DE DOCUMENTOS (extraído por IA) ===
' + resumenDocumentos }] }]
};

return [{ json: {
  faseId: webhookData.faseId,
  empresaId,
  claudeBody: JSON.stringify(requestBody)
} }];

// FIX: respuesta truncada por max_tokens → marcar error
if ($('Claude API - Analisis empresa').item.json.stop_reason === 'max_tokens') {
  const faseId = $('Code - Build Claude Request').item.json.faseId;
  const empresaId = $('Code - Build Claude Request').item.json.empresaId;
  const pliegoId = $('Code - Build Claude Request').item.json.pliegoId;
  return [{ json: {
    ...(faseId ? { faseId } : {}),
    ...(empresaId ? { empresaId } : {}),
    ...(pliegoId ? { pliegoId } : {}),
    empresasIds: $('Code - Build Claude Request').item.json.empresasIds,
    resultado: JSON.stringify({ error: 'respuesta_incompleta', mensaje: 'Respuesta de IA truncada — documento demasiado extenso' }),
    analisisPliego: JSON.stringify({ error: 'respuesta_incompleta' }),
    comparaciones: [],
    generalData: JSON.stringify({ error: 'respuesta_incompleta' }),
    porEmpresa: JSON.stringify({})
  } }];
}

const response = $('Claude API - Analisis empresa').item.json;
const buildData = $('Code - Build Claude Request').item.json;

let rawText = '';
if (response.content && response.content[0] && response.content[0].text) {
  rawText = response.content[0].text.trim().replace(/```json/g, '').replace(/```/g, '').trim();
}

let parsed = null;
try { parsed = JSON.parse(rawText); }
catch(e) { parsed = { error: 'respuesta_no_valida', raw: rawText.substring(0, 500) }; }

return [{ json: {
  faseId: buildData.faseId,
  empresaId: buildData.empresaId,
  resultado: JSON.stringify(parsed)
} }];

const webhookData = $('Webhook pliego-definitivo-empresa').item.json.body;
const documentosBase64 = webhookData.documentosBase64 || [];

const MAX_CHARS_PER_DOC = 80000;

function truncateText(text, maxChars) {
  if (!text || text.length <= maxChars) return text;
  const front = text.substring(0, Math.floor(maxChars * 0.7));
  const back = text.substring(text.length - Math.floor(maxChars * 0.25));
  return front + '\n...[OMITIDO: ' + (text.length - maxChars) + ' caracteres]...\n' + back;
}

const contentBlocks = [];
for (const doc of documentosBase64) {
  if (doc.textoExtraido) {
    contentBlocks.push({
      type: 'text',
      text: 'DOCUMENTO: ' + doc.nombre + '\n\n' + truncateText(doc.textoExtraido, MAX_CHARS_PER_DOC)
    });
  } else {
    contentBlocks.push({
      type: 'document',
      source: { type: 'base64', media_type: doc.mediaType, data: doc.base64 },
      title: doc.nombre
    });
  }
}
if (contentBlocks.length === 0) {
  contentBlocks.push({ type: 'text', text: 'Sin documentos adjuntos.' });
}

const haikuBody = {
  model: 'claude-haiku-4-5-20251001',
  max_tokens: 4096,
  system: 'Extrae y resume en máximo 500 palabras los puntos clave del documento adjunto: requisitos habilitantes (jurídico, financiero, técnico, experiencia), criterios de ponderación con sus pesos, fechas importantes, valores del contrato, alertas o cascaritas. Responde solo con el resumen estructurado.',
  messages: [{ role: 'user', content: contentBlocks }]
};

return [{ json: { haikuBody: JSON.stringify(haikuBody) } }];
